//! Strict decoding with the Python codecs fontTools picks for legacy name
//! records (`fontTools.misc.encodingTools`): Mac single-byte encodings, the
//! CJK double-byte codecs, and fontTools' `x_mac_*_ttx` extensions of them.
//! The tables in `tables.rs` and `*.bin` are generated from Python itself.

// generated by tests/data/regenerate.py, kept as written
#[rustfmt::skip]
mod tables;

use std::collections::HashMap;
use std::sync::OnceLock;

use crate::Error;

/// Byte pair -> character for a double-byte codec.
fn pairs(codec: &str) -> Option<&'static HashMap<u16, char>> {
    static PAIRS: OnceLock<HashMap<&'static str, HashMap<u16, char>>> = OnceLock::new();
    PAIRS
        .get_or_init(|| {
            tables::PAIRS
                .iter()
                .map(|&(name, mut data)| {
                    let mut map = HashMap::new();
                    let be = |d: &[u8], i: usize| u16::from_be_bytes([d[i], d[i + 1]]);
                    while !data.is_empty() {
                        let (start, count) = (be(data, 0), be(data, 2) as usize);
                        for i in 0..count {
                            let c = char::from_u32(be(data, 4 + 2 * i) as u32).unwrap();
                            map.insert(start + i as u16, c);
                        }
                        data = &data[4 + 2 * count..];
                    }
                    (name, map)
                })
                .collect()
        })
        .get(codec)
}

fn single(codec: &str) -> Option<&'static [u16; 256]> {
    tables::SINGLE
        .iter()
        .find(|(name, _)| *name == codec)
        .map(|(_, t)| t)
}

/// `bytes.decode(codec)` with strict errors, for the codecs in the tables.
/// Returns `None` for any other codec.
pub fn decode(codec: &str, bytes: &[u8]) -> Option<Result<String, Error>> {
    // an x_mac_*_ttx codec: its base codec, plus bytes it maps where the
    // base codec fails (fontTools' ExtendCodec error handler)
    let (base, extra): (&str, &[(u8, char)]) =
        match tables::EXTENDED.iter().find(|(name, _, _)| *name == codec) {
            Some(&(_, base, extra)) => (base, extra),
            None => (codec, &[]),
        };
    let lone = single(base)?;
    let pairs = pairs(base);
    let mut out = String::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if lone[b as usize] != 0xFFFF {
            out.push(char::from_u32(lone[b as usize] as u32).unwrap());
            i += 1;
        } else if let Some(c) = bytes
            .get(i + 1)
            .and_then(|t| pairs?.get(&(u16::from(b) << 8 | u16::from(*t))))
        {
            out.push(*c);
            i += 2;
        } else if let Some(&(_, c)) = extra.iter().find(|(x, _)| *x == b) {
            out.push(c);
            i += 1;
        } else {
            return Some(Err(format!(
                "'{codec}' codec can't decode byte 0x{b:02x} in position {i}"
            )
            .into()));
        }
    }
    Some(Ok(out))
}

#[cfg(test)]
mod tests {
    use super::decode;

    /// Random byte strings decoded by Python (`null`: UnicodeDecodeError).
    #[test]
    fn decoding_matches_python() {
        let cases: Vec<(String, String, Option<String>)> =
            serde_json::from_str(include_str!("../../tests/data/codec_cases.json")).unwrap();
        for (codec, hex, expected) in cases {
            let bytes: Vec<u8> = (0..hex.len())
                .step_by(2)
                .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
                .collect();
            let actual = decode(&codec, &bytes).expect(&codec).ok();
            assert_eq!(actual, expected, "{codec} {hex}");
        }
    }
}
